ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/a_symmetric_normal_deformation_realizes_the_forced_equal_order_ray.md';PREV=ROOT/'research/voevodsky/results/equal_order_necessity.json';RESULT=ROOT/'research/voevodsky/results/symmetric_equal_order_normal_deformation.json';Y0,q=s.symbols('Y0 q', nonzero=True);Y=Y0;X1=Y0+q;X2=-Y0+q;A=s.expand(X1+Y);B=s.expand(X1-Y);C=s.expand(X2+Y);D=s.expand(X2-Y);E=s.expand(X1+X2);order=lambda f:s.Poly(f,q).as_dict() and min(k[0] for k,v in s.Poly(f,q).terms() if v!=0);swap={Y0:-Y0};checks={'arrangement_identity':s.expand(E-(B+C))==0,'B_equals_q':B==q,'C_equals_q':C==q,'E_equals_2q':E==2*q,'all_orders_one':[order(z) for z in (B,C,E)]==[1,1,1],'A_nonzero_at_limit':A.subs(q,0)==2*Y0,'D_nonzero_at_limit':D.subs(q,0)==-2*Y0,'site_exchange_B_to_C':s.expand(B.subs(swap)-C)==0,'site_exchange_C_to_B':s.expand(C.subs(swap)-B)==0,'q_orientation_not_inferred':'Reversing \\(q\\) changes normal orientation but not vanishing order' in PACKET.read_text(encoding='utf-8'),'authority_gate':'no source map currently supplies the normal displacement' in PACKET.read_text(encoding='utf-8')};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.symmetric-equal-order-normal-deformation.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'necessity_result_sha256':sha256(PREV.read_bytes()).hexdigest(),'map':{'Y':'Y0','X1':'Y0+q','X2':'-Y0+q'},'factors':{'A':str(A),'B':str(B),'C':str(C),'D':str(D),'E':str(E)},'vanishing_orders':{'B':1,'C':1,'E':1},'checks':checks,'passed':all(checks.values()),'disposition':{'relative_normal_deformation':'constructed','site_symmetry':'verified','conductor_normal_authority':'missing','contour_orientation':'missing'}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
